  insert into questions (chapter_id, type, category, source, difficulty, stem_md, options_json, answer_key_md, marks, family, explanation_md)
  values
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'How is the modern periodic table arranged?', '["By increasing atomic mass","By decreasing reactivity","By number of neutrons","By increasing the proton number"]'::jsonb, 'D', 1, 'c528b81b9111', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which block of the periodic table contains the transition metals?', '["s-block","d-block","p-block","f-block"]'::jsonb, 'B', 1, '23ee7ad16dd8', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'An element has the electronic configuration 2,8,1. It belongs to:', '["Group 1","Group 18","Group 2","Group 17"]'::jsonb, 'A', 1, 'b5378fb9a068', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which element belongs to the same group as sodium?', '["Magnesium","Aluminium","Potassium","Chlorine"]'::jsonb, 'C', 1, 'fbd067f53ff8', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'What is the common name for the elements in Group 17?', '["Alkali metals","Noble gases","Alkaline earth metals","Halogens"]'::jsonb, 'D', 1, 'db4f9438c649', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'As you move from left to right across a period, the atomic radius generally:', '["Increases","Decreases","Remains constant","Doubles"]'::jsonb, 'B', 1, '48c41c502510', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Why do transition metals exhibit variable oxidation states?', '["They have large atomic radii.","They have very few electrons.","Their s and d subshell electrons are close enough in energy to be used in bonding.","They are all magnetic."]'::jsonb, 'C', 1, '3b83f13c0277', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which group of elements is known for having a full outermost electron shell, making them inert?', '["Alkali metals","Halogens","Noble gases","Transition metals"]'::jsonb, 'C', 1, 'c118dd579ca4', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'The "shielding effect" is most responsible for:', '["Preventing neutron decay","Making the nucleus larger","Increasing electronegativity","The ease of losing electrons in lower group elements"]'::jsonb, 'D', 1, '88b92f749dbf', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'The trend for atomic radius down a group is an increase because:', '["Proton number decreases","New electron shells are added","Electrons are lost","Electronegativity increases"]'::jsonb, 'B', 1, 'c072e131f459', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which element has the largest atomic radius?', '["Li","Na","K","Rb"]'::jsonb, 'D', 1, 'd2520f7daba1', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Lanthanides and actinides belong to:', '["s-block","p-block","d-block","f-block"]'::jsonb, 'D', 1, 'cd8e4bfe8669', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'What defines the "period" number of an element?', '["The number of valence electrons","The number of electron shells","The number of neutrons","The atomic mass"]'::jsonb, 'B', 1, 'e5f2c491b81e', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which element has the highest electronegativity?', '["Oxygen","Nitrogen","Fluorine","Chlorine"]'::jsonb, 'C', 1, 'c50b7cc8a4ad', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which element is expected to have the highest ionization energy?', '["Li","Be","B","Ne"]'::jsonb, 'D', 1, '45be7939ddb5', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which of these is a property of transition metals?', '["They are all gases at room temperature","They form colored compounds","They are highly electronegative","They have very low melting points"]'::jsonb, 'B', 1, '9f81f7ce9fa9', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'What does the group number indicate about the valence shell?', '["The number of inner shell electrons","The number of protons","The number of valence electrons","The number of neutrons"]'::jsonb, 'C', 1, '06d6de41256e', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Two elements are in the same group of the periodic table. Which property is most likely to be similar?', '["Number of valence electrons","Atomic mass","Number of shells","Atomic size"]'::jsonb, 'A', 1, '3c9e8dffce26', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'An element belongs to Period 3 and Group 16. How many occupied shells and valence electrons does it have?', '["16 shells, 3 valence electrons","3 shells, 6 valence electrons","3 shells, 16 valence electrons","6 shells, 3 valence electrons"]'::jsonb, 'B', 1, 'f9c54303a153', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'An element lies immediately to the right of sodium in the same period. Compared with sodium, it is expected to have:', '["Fewer protons","More occupied shells","Higher ionization energy","Larger atomic radius"]'::jsonb, 'C', 1, 'b91eb9e64ede', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'A student compares fluorine and chlorine. Which property increases from fluorine to chlorine?', '["Electron-attracting power","Electronegativity","Ionization energy","Atomic radius"]'::jsonb, 'D', 1, '06a4d23d9758', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which pair of elements is expected to show the greatest similarity in chemical behavior?', '["Li and Na","Mg and Al","Na and Mg","Cl and Ar"]'::jsonb, 'A', 1, 'f472c2a0b2b4', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'An element has the electronic configuration 2,8,8. What can be inferred about its chemical activity?', '["Highly reactive","Very unreactive","Moderately reactive","Reacts violently with water"]'::jsonb, 'B', 1, 'afd25b9217b6', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'An element in Group 2 forms ions by:', '["Gaining two electrons","Sharing eight electrons","Gaining one electron","Losing two electrons"]'::jsonb, 'D', 1, 'af811f77571b', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'The tendency of an atom to attract electrons in a bond is known to be highest for elements located:', '["Lower left of the periodic table","Upper right of the periodic table","Middle of the periodic table only","In Group 1"]'::jsonb, 'B', 1, '3cb80259303f', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which statement correctly compares sodium and chlorine?', '["Both readily lose electrons","Both belong to the same group","Both have identical chemical properties","Sodium tends to lose electrons, while chlorine tends to gain electrons"]'::jsonb, 'D', 1, '51e7aeb3088b', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'An element lies at the extreme right of a period. Which property is most likely?', '["Strong metallic character","Tendency to lose electrons easily","High stability due to a complete outer shell","Lowest ionization energy"]'::jsonb, 'C', 1, '10970df4a76c', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Why does the first ionization energy not strictly increase across Period 3, showing a slight dip between Magnesium and Aluminum?', '["Aluminum has a larger atomic radius than Magnesium.","Aluminum''s valence electron is in a p-subshell, which is slightly further from the nucleus and shielded by the s-subshell.","Magnesium has a higher nuclear charge than Aluminum.","Aluminum has more protons, which repel the valence electrons."]'::jsonb, 'B', 1, '56205fdd3652', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Why is the ionic radius of an O²⁻ ion significantly larger than that of a Ne atom, even though they have the same number of electrons?', '["Neon is a metal.","The oxygen nucleus is larger.","O²⁻ has fewer protons (8) pulling on the same number of electrons (10), resulting in less effective nuclear attraction.","They have the same nuclear charge."]'::jsonb, 'C', 1, '50d8236b9435', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'Consider elements X and Y in the same period. If X is a metal and Y is a non-metal, which is more likely to form an acidic oxide?', '["X","Y","Both are equally acidic.","Neither can form oxides."]'::jsonb, 'B', 1, '89b2fd5b8a12', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'What is the correct order of increasing atomic radius for the isoelectronic series N³⁻, O²⁻, F⁻, Ne, Na⁺?', '["N³⁻<O²⁻<F⁻<Ne<Na⁺","Na⁺<Ne<F⁻<O²⁻<N³⁻","Ne<Na⁺<N³⁻<O²⁻<F⁻","N³⁻=O²⁻=F⁻=Ne=Na⁺"]'::jsonb, 'B', 1, '44b94f71b83b', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Why is the ionic radius of a cation smaller than that of its neutral atom?', '["Cations lose an electron shell, and remaining electrons experience a higher effective nuclear charge.","Cations gain more protons.","Electrons are heavier than protons.","The nucleus disappears."]'::jsonb, 'A', 1, 'b5b8ab0a5428', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which block of the periodic table represents elements whose valence electrons are filling orbitals that are NOT the outermost shell?', '["s-block","p-block","d-block","All of the above."]'::jsonb, 'C', 1, '7c264b454bf9', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which factor causes the decrease in electron affinity from Chlorine to Bromine?', '["Bromine is a metal.","Loss of s-electrons.","Decreased nuclear charge.","Increased electron-electron repulsion in the larger 4p orbital."]'::jsonb, 'D', 1, '78fe31d24664', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Why are noble gases not truly "inert"?', '["Because they have no electrons.","Because larger ones (like Xenon) can be forced to react with highly electronegative elements like Fluorine.","Because they are all radioactive.","Because they are actually metals."]'::jsonb, 'B', 1, '62f6ad0461d0', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Why does the atomic radius of transition metals show a "dip" in the middle of the period?', '["Because protons are lost.","Because they become noble gases.","Because of the change in metallic bonding character as d-orbitals become half-filled.","Because they change into liquids."]'::jsonb, 'C', 1, '868ee27ad170', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'An element belongs to Group 17. Which statement CANNOT be true?', '["It contains seven valence electrons.","It forms a negative ion.","It is chemically inert.","It has a strong tendency to gain electrons."]'::jsonb, 'C', 1, 'cf29b7d7873b', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'The trend in boiling points for Group 17 (Halogens) is:', '["Increasing down the group due to increased Van der Waals forces.","Decreasing down the group.","Constant.","Random."]'::jsonb, 'A', 1, '35a5f9b6557e', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'What does a negative value for electron affinity mean?', '["The process is endothermic.","The process is exothermic.","The atom is a metal.","The atom is unstable."]'::jsonb, 'B', 1, '432406538f6b', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'Which property measures the "energy cost" of adding an electron?', '["Electronegativity","Ionization energy","Atomic radius","Electron affinity"]'::jsonb, 'D', 1, '2650ba8abd59', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'What is the relationship between atomic number and periodicity?', '["Periodicity is a function of the repetition of electronic configuration.","It is completely random.","It depends only on mass.","Protons define the color of the element."]'::jsonb, 'A', 1, '124ea4a32f9b', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'What differentiates the actinides from the lanthanides?', '["Actinides are all non-metals.","Lanthanides are larger.","Actinides have no electrons.","Lanthanides fill the 4f subshell, while actinides fill the 5f."]'::jsonb, 'D', 1, '4f3f621b52ce', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which of these sets represents an isoelectronic series where size is purely determined by proton count?', '["F⁻,Na⁺,Mg²⁺","Li,Be,B","Cl,Ar,K","O²⁻,S²⁻,Se²⁻"]'::jsonb, 'A', 1, 'ae3cbfe56ab0', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'In the Periodic Table, why is Helium often grouped with s-block elements in some theoretical models?', '["It is very dense.","It is a metal.","Its electronic configuration (1s²) matches the s-block filling pattern.","It reacts with oxygen."]'::jsonb, 'C', 1, 'c50927d747d5', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'The "Diagonal Relationship" between Lithium and Magnesium implies they share similar:', '["Atomic mass.","Melting points.","Charge density and polarization power.","Number of shells."]'::jsonb, 'C', 1, 'd4cb210c4451', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Why is atomic radius a "trend" rather than an absolute property for all elements in a period?', '["Because the periodic table is a diagram.","Because neutrons change the size.","Because atoms are always moving.","Because of varying metallic bonding strengths and orbital occupancy."]'::jsonb, 'D', 1, '3cb82a47a617', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'What is the most significant factor in the reactivity of Alkali metals?', '["High density.","High electronegativity.","Low first ionization energy.","Full valence shells."]'::jsonb, 'C', 1, '95cad9619d16', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'What does a high electronegativity value indicate about an atom''s behavior in a bond?', '["It has a strong tendency to attract shared electrons towards itself.","It donates electrons.","It is a poor electron attractor.","It becomes radioactive."]'::jsonb, 'A', 1, 'fd3f15c520dd', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Why does Carbon show unique bonding compared to other Group 14 elements?', '["It is a metal.","It has a small atomic radius, allowing it to form strong multiple bonds (pi-bonds).","It is a noble gas.","It has no protons."]'::jsonb, 'B', 1, 'd353108a9261', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which period contains the greatest number of elements?', '["Period 1","Period 7","Period 3","Period 2"]'::jsonb, 'B', 1, 'c186828d96c9', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'What trend is observed in the boiling points of Alkali metals down the group?', '["They increase.","They stay constant.","They decrease as the metallic bonding becomes weaker due to larger atomic size.","They are random."]'::jsonb, 'C', 1, '4bc388426c70', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which is the most reactive metal in the periodic table?', '["Li","Na","Mg","Cs"]'::jsonb, 'D', 1, 'b5dac6cad2ff', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Moving across a period, metallic character decreases mainly because atoms:', '["Hold valence electrons more strongly","Lose protons","Become larger","Gain shells"]'::jsonb, 'A', 1, '12a9b9f6f8b7', null);
